cat > spec/list_room.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\naoi\t2026-01-02\t13:00\t14:00\tz\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-01)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room with date"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = "$(printf '2026-01-01 10:00-11:00 aoi x\n2026-01-02 13:00-14:00 aoi z')" ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
BOOKINGS=$t bash src/list.sh --room aoi 2026-1-1 >/dev/null 2>&1; [ $? = 2 ] || { echo "list --room bad date exit"; fail=1; }
for args in "--room" "--room ''"; do
  out=$(BOOKINGS=$t eval "bash src/list.sh $args" 2>/tmp/list_room_err.$$); code=$?
  [ "$code" = 2 ] || { echo "list $args exit $code"; fail=1; }
  [ -z "$out" ] || { echo "list $args stdout not empty"; fail=1; }
  [ "$(cat /tmp/list_room_err.$$)" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list $args stderr"; fail=1; }
done
rm -f "$t" /tmp/list_room_err.$$; exit $fail
EOF
bash spec/list_room.spec.sh; echo "spec-exit=$?"; bash spec/list_date.spec.sh; echo "date-spec-exit=$?"; bash spec/list.spec.sh; echo "list-spec-exit=$?"

